import { test, expect } from '@playwright/test';
import {
  blockWrites, LOAD, CONVERSATION_ID, CONVERSATION_TITLE, expectConversationFillsMobileScreen, messageInput,
} from './open-conversation.helpers';

test.use({ storageState: '../auth/chat.json', serviceWorkers: 'block' });

test.describe('Чат / переписки — открытие переписки', () => {
  test('Мобайл: тап по переписке в списке «שיחות» открывает переписку на весь экран #bb6e6d @mobile @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto('/messages');
    const item = page.getByRole('heading', { name: CONVERSATION_TITLE });
    await expect(item).toBeAttached(LOAD);
    await expect(messageInput(page)).toHaveCount(0);

    // Пользователь долистал до списка
    await page.evaluate(() => window.scrollTo(0, 600));
    await item.click();

    await page.waitForURL((url) => url.searchParams.get('conversation') === CONVERSATION_ID);
    await expectConversationFillsMobileScreen(page);
  });
});
